/**
 * Japanese A2 — the Regular tier (10 paths × 10 lessons), per
 * docs/Product/FABLE_A2_LEARNING_PATH_DESIGN.md (§4 integration, §5 authoring
 * contract) and the spec in tmp\A2_JAPANESE_P1_P10_SPEC.md.
 *
 * Authoring contract highlights enforced in this module:
 * - Base locales are GERMAN + ENGLISH (matching Japanese A1, baseLanguage
 *   'German'): every GuidedBaseContentText field carries both .de and .en.
 * - Two-turn shape: sceneCaption carries the interlocutor's Japanese line quoted
 *   inside both base-locale captions; the learner's corePhrase is the response.
 * - WAKACHIGAKI (carried from A1): every target sentence field uses single ASCII
 *   spaces at word boundaries — particles attached to their host word, か
 *   attached to its verb, 。/、 attached to the preceding unit. The speech check
 *   scores CJK space-insensitively (lib/guidedSpeechCheck.ts).
 * - Register: です/ます EVERYWHERE, including the friend paths (P4/P8/P10) —
 *   Japanese A1 taught only polite forms and adults keep them with new friends;
 *   plain form (タメ口) is out of scope. Keigo beyond the fixed chunks
 *   (ありがとうございます) is banned.
 * - Tense contract: present everywhere; past -ました/-でした only from the spec
 *   whitelist (P3/P9 + marked recycling); plans/future = present + time word
 *   (Japanese has no morphological future). Japanese past never marks speaker
 *   gender — no agreement hazards.
 * - Numbers are kanji numeral words (三千円, 二つ, 十分), never digits.
 * - Trophies unique across the entire Japanese guided corpus (A1 + A2),
 *   particle-free single words.
 * - TTS-FROZEN (2026-07-17): the bright ElevenLabs batch ran for all 10 paths
 *   (profiles japanese_a2_bright_p{n}_multiv2_v1) — ids and TTS-bearing text
 *   (corePhrase/chunks/trophyWord) must NOT change without a regeneration plan.
 */
import type {
  GuidedBaseContentText,
  GuidedLessonDefinition,
  GuidedLessonStep,
  GuidedLessonTrophyWord,
  GuidedLessonVibeVariant,
  GuidedPathMetadata,
  LessonItem,
  PhraseChunk,
} from '../guidedLessons'
import { DEFAULT_GUIDED_VIBE_ID } from '../guidedVibes'

const JAPANESE_A2_GUIDED_TODAY_STEPS: GuidedLessonStep[] = ['scene', 'matchPairs', 'build', 'type', 'speak', 'complete']

type JapaneseA2VariantInput = {
  corePhrase: GuidedLessonVibeVariant['corePhrase']
  meaning: GuidedBaseContentText
  chunks: PhraseChunk[]
  lessonItems: LessonItem[]
  buildChips: string[]
  typeRecall: GuidedLessonVibeVariant['typeRecall']
  speakTarget: Omit<GuidedLessonVibeVariant['speakTarget'], 'language' | 'passingThreshold' | 'maxRecordingSeconds'>
  sceneCaption: GuidedBaseContentText
  trophyWord: GuidedLessonTrophyWord
  placeholderCaption: GuidedBaseContentText
  songMood: string
  visualNotes: string
}

export type JapaneseA2LessonInput = {
  slug: string
  title: GuidedBaseContentText
  situation: GuidedLessonDefinition['situation']
  pedagogicalGoal: string
  variant: GuidedLessonVibeVariant
}

function makeBrightJapaneseA2Variant(input: JapaneseA2VariantInput): GuidedLessonVibeVariant {
  return {
    contentStatus: 'draft',
    corePhrase: input.corePhrase,
    meaning: input.meaning,
    chunks: input.chunks,
    lessonItems: input.lessonItems,
    build: {
      targetText: input.corePhrase.targetText,
      chips: input.buildChips,
    },
    typeRecall: input.typeRecall,
    speakTarget: {
      ...input.speakTarget,
      language: 'ja-JP',
      // matches Japanese A1: CJK STT is noisier than Latin-script languages
      passingThreshold: 0.65,
      maxRecordingSeconds: 12,
    },
    sceneCaption: input.sceneCaption,
    trophyWord: input.trophyWord,
    placeholderMedia: {
      type: 'video',
      caption: input.placeholderCaption,
    },
    songSeed: {
      genre: 'bright Japanese acoustic',
      mood: input.songMood,
    },
    visualNotes: input.visualNotes,
  }
}

export function makeJapaneseA2PracticalLessons(
  metadata: GuidedPathMetadata,
  inputs: JapaneseA2LessonInput[],
  completionSituation: { de: string; en: string },
): GuidedLessonDefinition[] {
  const pathNumber = Number(metadata.id.replace('japanese-a2-practical-', ''))

  return inputs.map((lessonInput, index) => {
    const lessonNumber = index + 1
    const globalNumber = String((pathNumber - 1) * 10 + lessonNumber).padStart(3, '0')
    const id = `japanese-a2-practical-${pathNumber}-${globalNumber}-${lessonInput.slug}`
    const nextInput = inputs[index + 1]

    return {
      id,
      pathId: metadata.id,
      courseTitle: metadata.title,
      level: metadata.level,
      lessonNumber,
      baseLanguage: metadata.baseLanguage,
      targetLanguage: metadata.targetLanguage,
      pathMetadata: metadata,
      lessonMetadata: {
        id,
        sequence: lessonNumber,
        title: lessonInput.title,
      },
      title: lessonInput.title,
      situation: lessonInput.situation,
      pedagogicalGoal: lessonInput.pedagogicalGoal,
      modeSet: 'guided-today-v0',
      steps: JAPANESE_A2_GUIDED_TODAY_STEPS,
      estimatedMinutes: 5,
      fallbackVibeId: DEFAULT_GUIDED_VIBE_ID,
      status: 'active',
      nextLessonTeaser: {
        title: nextInput?.title ?? { de: 'Pfad abgeschlossen', en: 'Path complete' },
        situation: {
          de: nextInput?.situation.de ?? completionSituation.de,
          en: nextInput?.situation.en ?? completionSituation.en,
        },
      },
      vibeVariants: {
        bright: lessonInput.variant,
      },
    }
  })
}

export type JapaneseA2CompactLesson = {
  slug: string
  title: GuidedBaseContentText
  situation: GuidedLessonDefinition['situation']
  pedagogicalGoal: string
  targetText: string
  /** All-kana rendering of targetText when it contains kanji — becomes an accepted speak transcript variant. */
  targetKana?: string
  baseText: GuidedBaseContentText
  chunks: Array<{ targetText: string; baseText: GuidedBaseContentText }>
  /** kana = all-kana rendering accepted for typed answers when targetText contains kanji. */
  terms: Array<{ targetText: string; baseText: GuidedBaseContentText; kana?: string }>
  recall: { before: string; answer: string; after: string; kana?: string; fallbackChoices: string[] }
  /** Exactly three salient single wakachigaki units from the corePhrase, punctuation-free (できますか not できますか。), no spaces. */
  speakRequired: [string, string, string]
  sceneCaption: GuidedBaseContentText
  trophyWord: GuidedLessonTrophyWord
  distractors: [string, string]
  placeholderCaption: GuidedBaseContentText
  songMood: string
  visualNotes: string
}

/** Accepted answers: the exact text, its lowercase (identity for pure-CJK, needed for embedded Latin), and the all-kana variant when the text carries kanji. */
function japaneseA2Answers(text: string, kana?: string): string[] {
  return [...new Set([text, text.toLowerCase(), ...(kana && kana !== text ? [kana] : [])])]
}

function japaneseA2SpeakTokens(targetText: string, required: [string, string, string]): { requiredTokens: string[]; optionalTokens: string[] } {
  const requiredTokens = required.map((token) => token.toLowerCase())
  const optionalTokens = [...new Set(
    targetText
      .toLowerCase()
      .replace(/[^\p{L}\p{N}\s]/gu, ' ')
      .split(/\s+/)
      .filter(Boolean)
      .filter((word) => !requiredTokens.includes(word)),
  )]
  return { requiredTokens, optionalTokens }
}

export function makeJapaneseA2CompactLesson(input: JapaneseA2CompactLesson): JapaneseA2LessonInput {
  const prefix = input.slug.split('-')[0]
  return {
    slug: input.slug,
    title: input.title,
    situation: input.situation,
    pedagogicalGoal: input.pedagogicalGoal,
    variant: makeBrightJapaneseA2Variant({
      corePhrase: { targetText: input.targetText, baseText: input.baseText },
      meaning: input.baseText,
      chunks: input.chunks.map((chunk, index) => ({ id: `${prefix}-${index + 1}`, ...chunk })),
      lessonItems: input.terms.map((term, index) => ({
        id: `${prefix}-item-${index + 1}`,
        targetText: term.targetText,
        baseText: term.baseText,
        acceptedAnswers: japaneseA2Answers(term.targetText, term.kana),
      })),
      buildChips: [...input.chunks.map((chunk) => chunk.targetText), ...input.distractors],
      typeRecall: {
        before: input.recall.before,
        answer: input.recall.answer,
        after: input.recall.after,
        acceptedAnswers: japaneseA2Answers(input.recall.answer, input.recall.kana),
        fallbackChoices: input.recall.fallbackChoices,
      },
      speakTarget: {
        baseCue: input.baseText,
        targetPhrase: input.targetText,
        acceptedAnswers: [...new Set([input.targetText, ...(input.targetKana && input.targetKana !== input.targetText ? [input.targetKana] : [])])],
        ...japaneseA2SpeakTokens(input.targetText, input.speakRequired),
      },
      sceneCaption: input.sceneCaption,
      trophyWord: input.trophyWord,
      placeholderCaption: input.placeholderCaption,
      songMood: input.songMood,
      visualNotes: input.visualNotes,
    }),
  }
}

